function renderFilters(){$("filters").setAttribute("aria-label",lang==="en"?"Filter products":"فیلتر محصولات");$("filters").innerHTML=cats.map(c=>'<button type="button" class="filter '+(activeCat===c.id?'active':'')+'" data-cat="'+c.id+'" aria-pressed="'+String(activeCat===c.id)+'">'+c[lang]+'</button>').join("");$("filters").querySelectorAll("button").forEach(b=>b.addEventListener("click",()=>{activeCat=b.dataset.cat;renderFilters();renderProducts()}))}
function renderProducts(){const list=products.filter(p=>(activeCat==="all"||p.cat===activeCat)&&((p.name[lang]+" "+p.desc[lang]+" "+p.query).toLowerCase().includes(query.toLowerCase())));$("grid").innerHTML=list.length?list.map(p=>'<article class="product" data-category="'+p.cat+'"><div class="visual"><div class="poster-art">'+posterSVG(p)+'</div><span class="tag">'+(lang==="en"?p.tag:p.tagFa)+'</span></div><h3>'+esc(p.name[lang])+'</h3><p class="desc">'+esc(p.desc[lang])+'</p><div class="price">'+(lang==="en"?"Check current price":"بررسی قیمت روز")+'</div><a class="buy" href="'+amazonUrl(p.query)+'" target="_blank" rel="noopener noreferrer" aria-label="'+(lang==="en"?"Find ":"جست‌وجوی ")+esc(p.name[lang])+' on Amazon.ae"><span>'+(lang==="en"?"View on Amazon.ae":"مشاهده در Amazon.ae")+'</span><span aria-hidden="true">↗</span></a></article>').join(""):'<p class="empty">'+(lang==="en"?"No matching accessories. Try another search.":"محصولی پیدا نشد؛ عبارت دیگری را امتحان کنید.")+'</p>'}
function setLang(next){lang=next;document.documentElement.lang=lang;document.documentElement.dir=lang==="fa"?"rtl":"ltr";$("enBtn").classList.toggle("active",lang==="en");$("faBtn").classList.toggle("active",lang==="fa");$("enBtn").setAttribute("aria-pressed",String(lang==="en"));$("faBtn").setAttribute("aria-pressed",String(lang==="fa"));document.querySelectorAll("[data-en][data-fa]").forEach(el=>el.innerHTML=el.dataset[lang]);$("search").placeholder=$("search").dataset["placeholder"+(lang==="en"?"En":"Fa")];$("search").setAttribute("aria-label",lang==="en"?"Search products":"جست‌وجوی محصولات");renderFilters();renderProducts()}
